FIELD='.field private unicaDirectEpoch:J'
def patch(connector,runner):
 if FIELD in connector or 'UN1CA_CROWN_DIRECT_GATT_V8' in runner:
  if METHOD not in connector or INSERT not in runner:raise ValueError('Partial direct GATT patch')
  return connector,runner
 anchor='.field public A:J'
 if connector.count(anchor)!=1 or runner.count(HOOK)!=1:raise ValueError('Unsupported connector source')
 return connector.replace(anchor,anchor+'\n\n'+FIELD,1)+METHOD,runner.replace(HOOK,INSERT,1)
